input.text:
await new Promise(r => setTimeout(r, 3500));
[...document.querySelectorAll('pre.mermaid')].map((pre, i) => {
  const svg = pre.querySelector('svg');
  if (!svg) return {i, svg:false};
  const arrows=[...svg.querySelectorAll('path[data-id]')].filter(p=>p.getAttribute('marker-start')||p.getAttribute('marker-end')).map(p=>{
    const dir=p.getAttribute('marker-start')?'start':'end'; const len=p.getTotalLength(); const a=p.getPointAtLength(0), b=p.getPointAtLength(len);
    const head=dir==='start'?a:b, tail=dir==='start'?b:a; return p.getAttribute('data-id').replace(/_\d+$/,'')+':'+(head.y<tail.y-2?'上':head.y>tail.y+2?'下':'横');});
  const clusters=[...svg.querySelectorAll('g.cluster')].map(c=>[c.id.replace(/^.*?-(U\w+).*$/,'$1'), Math.round(c.querySelector('rect').getBoundingClientRect().top)]).sort((x,y)=>x[1]-y[1]).map(x=>x[0]);
  return {i, clusters: clusters.join('>'), arrows: arrows.join(' ')};
});

